final Map<String, dynamic> _yunqiLiterature = <String, dynamic>{"JZ60": {"甲子": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为太土(太宫),司天为少阴君火,在泉为阳明燥金,年支为子水\r\n不是平气之年", "LEVELIS": "0", "SAME": "甲子甲午岁，上少阴火，中太宫土运，下阳明金，热化二，雨化五，燥化四，所谓正化日也。其化上咸寒，中苦热，下酸热，所谓药食宜也。", "COM": "甲子甲午，其运阴雨，其化柔润时雨，其变震惊飘骤，其病中满身重。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "乙丑": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为少金(少商),司天为太阴湿土,在泉为太阳寒水,年支为丑土\r\n不是平气之年", "LEVELIS": "0", "SAME": "乙丑乙未岁，上太阴土，中少商金运，下太阳水，热化寒化胜复同，所谓邪气化日也。灾七宫。湿化五，清化四，寒化六，所谓正化日也。其化上苦热，中酸和，下甘热，所谓药食宜也。", "COM": "乙丑乙未，其运凉热寒。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "丙寅": {"STR": "运气异化", "NAME": "不和年", "IF": "运克气,以运为主", "LEVELSTR": "岁运为太水(太羽),司天为少阳相火,在泉为厥阴风木,年支为寅木\r\n不是平气之年", "LEVELIS": "0", "SAME": "丙寅丙申岁，上少阳相火，中太羽水运，下厥阴木。火化二，寒化六，风化三，所谓正化日也。其化上咸寒，中咸温下辛温，所谓药食宜也。", "COM": "丙寅丙申，其运寒肃，其化凝惨凓冽，其变冰雪霜雹，其病寒浮肿。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "丁卯": {"STR": "运气同化", "NAME": "岁会", "IF": "中行令者，其病徐而持", "LEVELSTR": "岁运为少木(少角),司天为阳明燥金,在泉为少阴君火,年支为卯木\r\n岁运不及得地支之气的资助,是平气之年", "LEVELIS": "1", "SAME": "丁卯丁酉岁，上阳明金，中少角木运，下少阴火，清化热化胜复同，所谓邪气化日也。灾三宫。燥化九，风化三，热化七，所谓正化日也。其化上苦小温，中辛和，下咸寒，所谓药食宜也。", "COM": "丁卯岁会丁酉，其运风清热凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "戊辰": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为太火(太徵),司天为太阳寒水,在泉为太阴湿土,年支为辰土\r\n岁运太过得司天之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "戊辰戊戌岁，上太阳水，中太徵火运，下太阴土。寒化六，热化七，湿化五，所谓正化日也。其化上苦温，中甘和，下甘温，所谓药食宜也。", "COM": "戊辰戊戌同正徵，其运热，其化暄暑郁燠，其变炎烈沸腾，其病热郁。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "己巳": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为少土(少宫),司天为厥阴风木,在泉为少阳相火,年支为巳火\r\n不是平气之年", "LEVELIS": "0", "SAME": "己巳己亥岁，上厥阴木，中少宫土运，下少阳相火，风化清化胜复同，所谓邪气化日也。灾五宫。风化三，湿化五，火化七，所谓正化日也。其化上辛凉，中甘和，下咸寒，所谓药食宜也。", "COM": "己巳己亥，其运雨风清。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "庚午": {"STR": "运气同化", "NAME": "同天符", "IF": "", "LEVELSTR": "岁运为太金(太商),司天为少阴君火,在泉为阳明燥金,年支为午火\r\n岁运太过得司天之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "庚午庚子岁，上少阴火，中太商金运，下阳明金，热化七，清化九，燥化九，所谓正化日也。其化上咸寒，中辛温，下酸温，所谓药食宜也。", "COM": "庚子庚午同正商。其运凉劲，其化雾露萧飋，其变肃杀凋零，其病下清。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "辛未": {"STR": "运气同化", "NAME": "同岁会", "IF": "", "LEVELSTR": "岁运为少水(少羽),司天为太阴湿土,在泉为太阳寒水,年支为未土\r\n不是平气之年", "LEVELIS": "0", "SAME": "辛未辛丑岁，上太阴土，中少羽水运，下太阳水，雨化风化胜复同，所谓邪气化日也。灾一宫。雨化五，寒化一，所谓正化日也。其化上苦热，中苦和，下苦热，所谓药食宜也。", "COM": "辛丑辛未，其运寒雨风。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "壬申": {"STR": "运气同化", "NAME": "同天符", "IF": "", "LEVELSTR": "岁运为太木(太角),司天为少阳相火,在泉为厥阴风木,年支为申金\r\n岁运太过得地支之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "壬申壬寅岁，上少阳相火，中太角木运，下厥阴木，火化二，风化八，所谓正化日也。其化土咸寒，中酸和，下辛凉，所谓药食宜也。", "COM": "壬寅壬申，其运风鼓，其化鸣紊启坼，其变振拉摧拔，其病掉眩，支胁，惊骇。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "癸酉": {"STR": "运气同化", "NAME": "同岁会", "IF": "", "LEVELSTR": "岁运为少火(少徵),司天为阳明燥金,在泉为少阴君火,年支为酉金\r\n不是平气之年", "LEVELIS": "0", "SAME": "癸酉癸卯岁，上阳明金，中少徵火运，下少阴火，寒化雨化胜复同，所谓邪气化日也。灾九宫。燥化九，热化二，所谓正化日也。其化上苦小温，中咸温，下咸寒，所谓药食宜也。", "COM": "癸卯癸酉，其运热寒雨。凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "甲戌": {"STR": "运气同化", "NAME": "岁会,同天符", "IF": "中行令者，其病徐而持", "LEVELSTR": "岁运为太土(太宫),司天为太阳寒水,在泉为太阴湿土,年支为戌土\r\n不是平气之年", "LEVELIS": "0", "SAME": "甲戌甲辰岁，上太阳水，中太宫土运，下太阴土，寒化六，湿化五，正化日也。其化上苦热，中苦温，下苦温，药食宜也。", "COM": "甲辰岁会甲戌岁会，其运阴埃，其化柔润重泽，其变震惊飘骤，其病湿下重。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "乙亥": {"STR": "运气异化", "NAME": "", "IF": "", "LEVELSTR": "岁运为少金(少商),司天为厥阴风木,在泉为少阳相火,年支为亥水\r\n不是平气之年", "LEVELIS": "0", "SAME": "乙亥乙巳岁，上厥阴木，中少商金运，下少阳相火，热化寒化胜复同，邪气化日也。灾七宫。风化八，清化四，火化二，正化度也。其化上辛凉，中酸和，下咸寒，药食宜也。", "COM": "乙巳乙亥，其运凉热寒。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "丙子": {"STR": "运气同化", "NAME": "岁会", "IF": "中行令者，其病徐而持", "LEVELSTR": "岁运为太水(太羽),司天为少阴君火,在泉为阳明燥金,年支为子水\r\n不是平气之年", "LEVELIS": "0", "SAME": "丙子丙午岁，上少阴火，中太羽水运，下阳明金，热化二，寒化六，清化四，正化度也。其化上咸寒，中咸热，下酸温，药食宜也。", "COM": "丙子岁会丙午，其运寒，其化凝惨凓冽，其变冰雪霜雹，其病寒下。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "丁丑": {"STR": "运气异化", "NAME": "不和年", "IF": "运克气,以运为主", "LEVELSTR": "岁运为少木(少角),司天为太阴湿土,在泉为太阳寒水,年支为丑土\r\n不是平气之年", "LEVELIS": "0", "SAME": "丁丑丁未岁，上太阴土，中少角木运，下太阳水，清化热化胜复同，邪气化度也。灾三宫。雨化五，风化三，寒化一，正化度也。其化上苦温，中辛温，下甘热，药食宜也。", "COM": "丁丑丁未，其运风清热.凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "戊寅": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为太火(太徵),司天为少阳相火,在泉为厥阴风木,年支为寅木\r\n不是平气之年", "LEVELIS": "0", "SAME": "戊寅戊申岁，上少阳相火，中太徵火运，下厥阴木，火化七，风化三，正化度也。其化上咸寒，中甘和，下辛凉，药食宜也。", "COM": "戊寅天符戊申天符，其运暑，其化暄嚣郁燠，其变炎烈沸腾，其病上热郁，血溢血泄心痛。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "己卯": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为少土(少宫),司天为阳明燥金,在泉为少阴君火,年支为卯木\r\n不是平气之年", "LEVELIS": "0", "SAME": "己卯己酉岁，上阳明金，中少宫土运，下少阴火，风化清化胜复同，邪气化度也。灾五宫。清化九，雨化五，热化七，正化度也，其化上苦小温，中甘和，下咸寒，药食宜也。", "COM": "己卯己酉，其运雨风凉。凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "庚辰": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为太金(太商),司天为太阳寒水,在泉为太阴湿土,年支为辰土\r\n不是平气之年", "LEVELIS": "0", "SAME": "庚辰庚戌岁，上太阳水，中太商金运，下太阴土。寒化一，清化九，雨化五，正化度也。其化上苦热，中辛温，下甘热，药食宜也。", "COM": "庚辰庚戌，其运凉，其化雾露萧，其变肃杀凋零，其病燥背瞀胸满。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "辛巳": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为少水(少羽),司天为厥阴风木,在泉为少阳相火,年支为巳火\r\n不是平气之年", "LEVELIS": "0", "SAME": "辛巳辛亥岁，上厥阴木，中少羽水运，下少阳相火，雨化风化胜复同，邪气化度也。灾一宫。风化三，寒化一，火化七，正化度也。其化上辛凉，中苦和，下咸寒，药食宜也。", "COM": "辛巳辛亥，其运寒雨风。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "壬午": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为太木(太角),司天为少阴君火,在泉为阳明燥金,年支为午火\r\n不是平气之年", "LEVELIS": "0", "SAME": "壬午壬子岁，上少阴火，中太角木运，下阳明金。热化二，风化八，清化四，正化度也。其化上咸寒，中酸凉，下酸温，药食宜也。", "COM": "壬子壬午，其运风鼓，其化鸣紊启折，其变振拉摧拔，其病支满。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "癸未": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为少火(少徵),司天为太阴湿土,在泉为太阳寒水,年支为未土\r\n不是平气之年", "LEVELIS": "0", "SAME": "癸未癸丑岁，上太阴土，中少徵火运，下太阳水，寒化雨化胜复同，邪气化度也。灾九宫。雨化五，火化二，寒化一，正化度也。其化上苦温，中咸温，下甘热，药食宜也。", "COM": "癸丑癸未，其运热寒雨。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "甲申": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为太土(太宫),司天为少阳相火,在泉为厥阴风木,年支为申金\r\n不是平气之年", "LEVELIS": "0", "SAME": "甲申甲寅岁，上少阳相火，中太宫土运，下厥阴木。火化二，雨化五，风化八，正化度也。其化上咸寒，中咸和，下辛凉，药食宜也。", "COM": "甲寅甲申，其运阴雨，其化柔润重泽，其变震惊飘骤，其病体重，胕肿痞饮。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "乙酉": {"STR": "运气同化", "NAME": "天符,岁会,即太乙天符", "IF": "中贵人者，其病暴而死", "LEVELSTR": "岁运为少金(少商),司天为阳明燥金,在泉为少阴君火,年支为酉金\r\n岁运不及得司天之气的资助,是平气之年", "LEVELIS": "1", "SAME": "乙酉乙卯岁，上阳明金，中少商金运，下少阴火，热化寒化胜复同，邪气化度也。灾七宫。燥化四，清化四，热化二，正化度也。其化上苦小温，中苦和，下咸寒，药食宜也。", "COM": "乙卯天符，乙酉岁会，太一天符，其运凉热寒。凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "丙戌": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为太水(太羽),司天为太阳寒水,在泉为太阴湿土,年支为戌土\r\n岁运太过得地支之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "丙戌丙辰岁，上太阳水，中太羽水运，下太阴土。寒化六，雨化五，正化度也。其化上苦热，中咸温，下甘热，药食宜也。", "COM": "丙辰天符丙戌天符，其运寒，其化凝惨凓冽，其变冰雪霜雹，其病大寒留于谿谷。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "丁亥": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为少木(少角),司天为厥阴风木,在泉为少阳相火,年支为亥水\r\n岁运不及得司天之气的资助,是平气之年", "LEVELIS": "1", "SAME": "丁亥丁巳岁，上厥阴木，中少角木运，下少阳相火，清化热化胜复同，邪气化度也。灾三宫。风化三，火化七，正化度也。其化上辛凉，中辛和，下咸寒，药食宜也。", "COM": "。丁巳天符，丁亥天符，其运风清热。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "戊子": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为太火(太徵),司天为少阴君火,在泉为阳明燥金,年支为子水\r\n岁运太过得地支之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "戊子戊午岁，上少阴火，中太徵火运，下阳明金。热化七，清化九，正化度也。其化上咸寒，中甘寒，下酸温，药食宜也。", "COM": "戊子天符戊午太一天符，其运炎暑，其化暄曜郁燠，其变炎烈沸腾，其病上热血溢。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "己丑": {"STR": "运气同化", "NAME": "天符,岁会,即太乙天符", "IF": "中贵人者，其病暴而死", "LEVELSTR": "岁运为少土(少宫),司天为太阴湿土,在泉为太阳寒水,年支为丑土\r\n岁运不及得司天之气的资助,是平气之年", "LEVELIS": "1", "SAME": "己丑己未岁，上太阴土，中少宫土运，下太阳水，风化清化胜复同，邪气化度也。灾五宫。雨化五，寒化一，正化度也。其化上苦热，中甘和，下甘热，药食宜也。", "COM": "己丑太一天符，己未太一天符，其运雨风清。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "庚寅": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为太金(太商),司天为少阳相火,在泉为厥阴风木,年支为寅木\r\n岁运太过得司天之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "庚寅庚申岁，上少阳相火，中太商金运，下厥阴木。火化七，清化九，风化三，正化度也。其化上咸寒，中辛温，下辛凉，药食宜也。", "COM": "庚寅庚申同正商，其运凉，其化雾露清切，其变肃杀凋零，其病肩背胸中。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "辛卯": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为少水(少羽),司天为阳明燥金,在泉为少阴君火,年支为卯木\r\n不是平气之年", "LEVELIS": "0", "SAME": "辛卯辛酉岁，上阳明金，中少羽水运，下少阴火，雨化风化胜复同，邪气化度也。灾一宫。清化九，寒化一，热化七，正化度也。其化上苦小温，中苦和，下咸寒，药食宜也。", "COM": "辛酉辛卯其运寒雨风凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "壬辰": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为太木(太角),司天为太阳寒水,在泉为太阴湿土,年支为辰土\r\n不是平气之年", "LEVELIS": "0", "SAME": "壬辰壬戌岁，上太阳水，中太角木运，下太阴土。寒化六，风化八，雨化五，正化度也。其化上苦温，中酸和，下甘温，药食宜也。", "COM": "壬辰壬戌，其运风，其化鸣紊启拆，其变振拉摧拔，其病眩掉目瞑。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "癸巳": {"STR": "运气同化", "NAME": "同岁会", "IF": "", "LEVELSTR": "岁运为少火(少徵),司天为厥阴风木,在泉为少阳相火,年支为巳火\r\n岁运不及得地支之气的资助,是平气之年", "LEVELIS": "1", "SAME": "癸巳癸亥岁，上厥阴木，中少徵火运，下少阳相火，寒化雨化胜复同，邪气化度也。灾九宫。风化八，火化二，正化度也。其化上辛凉，中咸和，下咸寒，药食宜也。", "COM": "癸巳癸亥，其运热寒雨凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "甲午": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为太土(太宫),司天为少阴君火,在泉为阳明燥金,年支为午火\r\n不是平气之年", "LEVELIS": "0", "SAME": "甲子甲午岁，上少阴火，中太宫土运，下阳明金，热化二，雨化五，燥化四，所谓正化日也。其化上咸寒，中苦热，下酸热，所谓药食宜也。", "COM": "甲子甲午，其运阴雨，其化柔润时雨，其变震惊飘骤，其病中满身重。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "乙未": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为少金(少商),司天为太阴湿土,在泉为太阳寒水,年支为未土\r\n不是平气之年", "LEVELIS": "0", "SAME": "乙丑乙未岁，上太阴土，中少商金运，下太阳水，热化寒化胜复同，所谓邪气化日也。灾七宫。湿化五，清化四，寒化六，所谓正化日也。其化上苦热，中酸和，下甘热，所谓药食宜也。", "COM": "乙丑乙未，其运凉热寒。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "丙申": {"STR": "运气异化", "NAME": "不和年", "IF": "运克气,以运为主", "LEVELSTR": "岁运为太水(太羽),司天为少阳相火,在泉为厥阴风木,年支为申金\r\n不是平气之年", "LEVELIS": "0", "SAME": "丙寅丙申岁，上少阳相火，中太羽水运，下厥阴木。火化二，寒化六，风化三，所谓正化日也。其化上咸寒，中咸温下辛温，所谓药食宜也。", "COM": "丙寅丙申，其运寒肃，其化凝惨凓冽，其变冰雪霜雹，其病寒浮肿。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "丁酉": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为少木(少角),司天为阳明燥金,在泉为少阴君火,年支为酉金\r\n不是平气之年", "LEVELIS": "0", "SAME": "丁卯丁酉岁，上阳明金，中少角木运，下少阴火，清化热化胜复同，所谓邪气化日也。灾三宫。燥化九，风化三，热化七，所谓正化日也。其化上苦小温，中辛和，下咸寒，所谓药食宜也。", "COM": "丁卯岁会丁酉，其运风清热凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "戊戌": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为太火(太徵),司天为太阳寒水,在泉为太阴湿土,年支为戌土\r\n岁运太过得司天之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "戊辰戊戌岁，上太阳水，中太徵火运，下太阴土。寒化六，热化七，湿化五，所谓正化日也。其化上苦温，中甘和，下甘温，所谓药食宜也。", "COM": "戊辰戊戌同正徵，其运热，其化暄暑郁燠，其变炎烈沸腾，其病热郁。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "己亥": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为少土(少宫),司天为厥阴风木,在泉为少阳相火,年支为亥水\r\n不是平气之年", "LEVELIS": "0", "SAME": "己巳己亥岁，上厥阴木，中少宫土运，下少阳相火，风化清化胜复同，所谓邪气化日也。灾五宫。风化三，湿化五，火化七，所谓正化日也。其化上辛凉，中甘和，下咸寒，所谓药食宜也。", "COM": "己巳己亥，其运雨风清。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "庚子": {"STR": "运气同化", "NAME": "同天符", "IF": "", "LEVELSTR": "岁运为太金(太商),司天为少阴君火,在泉为阳明燥金,年支为子水\r\n岁运太过得司天之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "庚午庚子岁，上少阴火，中太商金运，下阳明金，热化七，清化九，燥化九，所谓正化日也。其化上咸寒，中辛温，下酸温，所谓药食宜也。", "COM": "庚子庚午同正商。其运凉劲，其化雾露萧飋，其变肃杀凋零，其病下清。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "辛丑": {"STR": "运气同化", "NAME": "同岁会", "IF": "", "LEVELSTR": "岁运为少水(少羽),司天为太阴湿土,在泉为太阳寒水,年支为丑土\r\n不是平气之年", "LEVELIS": "0", "SAME": "辛未辛丑岁，上太阴土，中少羽水运，下太阳水，雨化风化胜复同，所谓邪气化日也。灾一宫。雨化五，寒化一，所谓正化日也。其化上苦热，中苦和，下苦热，所谓药食宜也。", "COM": "辛丑辛未，其运寒雨风。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "壬寅": {"STR": "运气同化", "NAME": "同天符", "IF": "", "LEVELSTR": "岁运为太木(太角),司天为少阳相火,在泉为厥阴风木,年支为寅木\r\n不是平气之年", "LEVELIS": "0", "SAME": "壬申壬寅岁，上少阳相火，中太角木运，下厥阴木，火化二，风化八，所谓正化日也。其化土咸寒，中酸和，下辛凉，所谓药食宜也。", "COM": "壬寅壬申，其运风鼓，其化鸣紊启坼，其变振拉摧拔，其病掉眩，支胁，惊骇。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "癸卯": {"STR": "运气同化", "NAME": "同岁会", "IF": "", "LEVELSTR": "岁运为少火(少徵),司天为阳明燥金,在泉为少阴君火,年支为卯木\r\n不是平气之年", "LEVELIS": "0", "SAME": "癸酉癸卯岁，上阳明金，中少徵火运，下少阴火，寒化雨化胜复同，所谓邪气化日也。灾九宫。燥化九，热化二，所谓正化日也。其化上苦小温，中咸温，下咸寒，所谓药食宜也。", "COM": "癸卯癸酉，其运热寒雨。凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "甲辰": {"STR": "运气同化", "NAME": "岁会,同天符", "IF": "中行令者，其病徐而持", "LEVELSTR": "岁运为太土(太宫),司天为太阳寒水,在泉为太阴湿土,年支为辰土\r\n不是平气之年", "LEVELIS": "0", "SAME": "甲戌甲辰岁，上太阳水，中太宫土运，下太阴土，寒化六，湿化五，正化日也。其化上苦热，中苦温，下苦温，药食宜也。", "COM": "甲辰岁会甲戌岁会，其运阴埃，其化柔润重泽，其变震惊飘骤，其病湿下重。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "乙巳": {"STR": "运气异化", "NAME": "不和年", "IF": "运克气,以运为主", "LEVELSTR": "岁运为少金(少商),司天为厥阴风木,在泉为少阳相火,年支为巳火\r\n不是平气之年", "LEVELIS": "0", "SAME": "乙亥乙巳岁，上厥阴木，中少商金运，下少阳相火，热化寒化胜复同，邪气化日也。灾七宫。风化八，清化四，火化二，正化度也。其化上辛凉，中酸和，下咸寒，药食宜也。", "COM": "乙巳乙亥，其运凉热寒。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "丙午": {"STR": "运气异化", "NAME": "不和年", "IF": "运克气,以运为主", "LEVELSTR": "岁运为太水(太羽),司天为少阴君火,在泉为阳明燥金,年支为午火\r\n不是平气之年", "LEVELIS": "0", "SAME": "丙子丙午岁，上少阴火，中太羽水运，下阳明金，热化二，寒化六，清化四，正化度也。其化上咸寒，中咸热，下酸温，药食宜也。", "COM": "丙子岁会丙午，其运寒，其化凝惨凓冽，其变冰雪霜雹，其病寒下。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "丁未": {"STR": "运气异化", "NAME": "不和年", "IF": "运克气,以运为主", "LEVELSTR": "岁运为少木(少角),司天为太阴湿土,在泉为太阳寒水,年支为未土\r\n不是平气之年", "LEVELIS": "0", "SAME": "丁丑丁未岁，上太阴土，中少角木运，下太阳水，清化热化胜复同，邪气化度也。灾三宫。雨化五，风化三，寒化一，正化度也。其化上苦温，中辛温，下甘热，药食宜也。", "COM": "丁丑丁未，其运风清热凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "戊申": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为太火(太徵),司天为少阳相火,在泉为厥阴风木,年支为申金\r\n不是平气之年", "LEVELIS": "0", "SAME": "戊寅戊申岁，上少阳相火，中太徵火运，下厥阴木，火化七，风化三，正化度也。其化上咸寒，中甘和，下辛凉，药食宜也。", "COM": "戊寅天符戊申天符，其运暑，其化暄嚣郁燠，其变炎烈沸腾，其病上热郁，血溢血泄心痛。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "己酉": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为少土(少宫),司天为阳明燥金,在泉为少阴君火,年支为酉金\r\n不是平气之年", "LEVELIS": "0", "SAME": "己卯己酉岁，上阳明金，中少宫土运，下少阴火，风化清化胜复同，邪气化度也。灾五宫。清化九，雨化五，热化七，正化度也，其化上苦小温，中甘和，下咸寒，药食宜也。", "COM": "己卯己酉，其运雨风凉。凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "庚戌": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为太金(太商),司天为太阳寒水,在泉为太阴湿土,年支为戌土\r\n不是平气之年", "LEVELIS": "0", "SAME": "庚辰庚戌岁，上太阳水，中太商金运，下太阴土。寒化一，清化九，雨化五，正化度也。其化上苦热，中辛温，下甘热，药食宜也。", "COM": "庚辰庚戌，其运凉，其化雾露萧，其变肃杀凋零，其病燥背瞀胸满。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "辛亥": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为少水(少羽),司天为厥阴风木,在泉为少阳相火,年支为亥水\r\n岁运不及得地支之气的资助,是平气之年", "LEVELIS": "1", "SAME": "辛巳辛亥岁，上厥阴木，中少羽水运，下少阳相火，雨化风化胜复同，邪气化度也。灾一宫。风化三，寒化一，火化七，正化度也。其化上辛凉，中苦和，下咸寒，药食宜也。", "COM": "辛巳辛亥，其运寒雨风。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "壬子": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为太木(太角),司天为少阴君火,在泉为阳明燥金,年支为子水\r\n不是平气之年", "LEVELIS": "0", "SAME": "壬午壬子岁，上少阴火，中太角木运，下阳明金。热化二，风化八，清化四，正化度也。其化上咸寒，中酸凉，下酸温，药食宜也。", "COM": "壬子壬午，其运风鼓，其化鸣紊启折，其变振拉摧拔，其病支满。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "癸丑": {"STR": "运气异化", "NAME": "小逆年", "IF": "运生气,以运为主", "LEVELSTR": "岁运为少火(少徵),司天为太阴湿土,在泉为太阳寒水,年支为丑土\r\n不是平气之年", "LEVELIS": "0", "SAME": "癸未癸丑岁，上太阴土，中少徵火运，下太阳水，寒化雨化胜复同，邪气化度也。灾九宫。雨化五，火化二，寒化一，正化度也。其化上苦温，中咸温，下甘热，药食宜也。", "COM": "癸丑癸未，其运热寒雨。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "甲寅": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为太土(太宫),司天为少阳相火,在泉为厥阴风木,年支为寅木\r\n岁运太过得地支之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "甲申甲寅岁，上少阳相火，中太宫土运，下厥阴木。火化二，雨化五，风化八，正化度也。其化上咸寒，中咸和，下辛凉，药食宜也。", "COM": "甲寅甲申，其运阴雨，其化柔润重泽，其变震惊飘骤，其病体重，胕肿痞饮。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "乙卯": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为少金(少商),司天为阳明燥金,在泉为少阴君火,年支为卯木\r\n岁运不及得司天之气的资助,是平气之年", "LEVELIS": "1", "SAME": "乙酉乙卯岁，上阳明金，中少商金运，下少阴火，热化寒化胜复同，邪气化度也。灾七宫。燥化四，清化四，热化二，正化度也。其化上苦小温，中苦和，下咸寒，药食宜也。", "COM": "乙卯天符，乙酉岁会，太一天符，其运凉热寒。凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "丙辰": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为太水(太羽),司天为太阳寒水,在泉为太阴湿土,年支为辰土\r\n岁运太过得地支之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "丙戌丙辰岁，上太阳水，中太羽水运，下太阴土。寒化六，雨化五，正化度也。其化上苦热，中咸温，下甘热，药食宜也。", "COM": "丙辰天符丙戌天符，其运寒，其化凝惨凓冽，其变冰雪霜雹，其病大寒留于谿谷。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "丁巳": {"STR": "运气同化", "NAME": "天符", "IF": "中执法者，其病速而危", "LEVELSTR": "岁运为少木(少角),司天为厥阴风木,在泉为少阳相火,年支为巳火\r\n岁运不及得司天之气的资助,是平气之年", "LEVELIS": "1", "SAME": "丁亥丁巳岁，上厥阴木，中少角木运，下少阳相火，清化热化胜复同，邪气化度也。灾三宫。风化三，火化七，正化度也。其化上辛凉，中辛和，下咸寒，药食宜也。", "COM": "。丁巳天符，丁亥天符，其运风清热。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}, "戊午": {"STR": "运气同化", "NAME": "天符,岁会,即太乙天符", "IF": "中贵人者，其病暴而死", "LEVELSTR": "岁运为太火(太徵),司天为少阴君火,在泉为阳明燥金,年支为午火\r\n不是平气之年", "LEVELIS": "0", "SAME": "戊子戊午岁，上少阴火，中太徵火运，下阳明金。热化七，清化九，正化度也。其化上咸寒，中甘寒，下酸温，药食宜也。", "COM": "戊子天符戊午太一天符，其运炎暑，其化暄曜郁燠，其变炎烈沸腾，其病上热血溢。凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏，目赤，眥疡，寒厥入胃，心痛，腰痛，腹大，嗌干肿上。岁宜咸以之，而调其上，甚则以苦发之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化，用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也，反是者病作矣。"}, "己未": {"STR": "运气同化", "NAME": "天符,岁会,即太乙天符", "IF": "中贵人者，其病暴而死", "LEVELSTR": "岁运为少土(少宫),司天为太阴湿土,在泉为太阳寒水,年支为未土\r\n岁运不及得司天之气的资助,是平气之年", "LEVELIS": "1", "SAME": "己丑己未岁，上太阴土，中少宫土运，下太阳水，风化清化胜复同，邪气化度也。灾五宫。雨化五，寒化一，正化度也。其化上苦热，中甘和，下甘热，药食宜也。", "COM": "己丑太一天符，己未太一天符，其运雨风清。凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满，身（月真）愤，胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。故有余宜高，不及宜下，有余宜晚，不及宜早，土之利，气之化也，民气亦从之，间谷命其太也。故岁宜以苦燥之温之，甚者发之泄之。不发不泄，则湿气外溢，肉溃皮拆而水血交流。必赞其阳火，令御甚寒，从气异同，少多其判也，同寒者以热化，同湿者以燥化，异者少之，同者多之，用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也，反是者病也。"}, "庚申": {"STR": "运气异化", "NAME": "天刑年", "IF": "气克运,以气为主", "LEVELSTR": "岁运为太金(太商),司天为少阳相火,在泉为厥阴风木,年支为申金\r\n岁运太过得司天之气的抑制,是平气之年", "LEVELIS": "1", "SAME": "庚寅庚申岁，上少阳相火，中太商金运，下厥阴木。火化七，清化九，风化三，正化度也。其化上咸寒，中辛温，下辛凉，药食宜也。", "COM": "庚寅庚申同正商，其运凉，其化雾露清切，其变肃杀凋零，其病肩背胸中。凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应，火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化，用热远热，用温远温，用寒远寒，用凉远凉，食宜同法，此其道也。有假者反之，反是者，病之阶也。"}, "辛酉": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为少水(少羽),司天为阳明燥金,在泉为少阴君火,年支为酉金\r\n不是平气之年", "LEVELIS": "0", "SAME": "辛卯辛酉岁，上阳明金，中少羽水运，下少阴火，雨化风化胜复同，邪气化度也。灾一宫。清化九，寒化一，热化七，正化度也。其化上苦小温，中苦和，下咸寒，药食宜也。", "COM": "辛酉辛卯其运寒雨风凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者，其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴，蛰虫乃见，流水不冰，民病咳嗌塞，寒热发，暴振凓癃閟，清先而劲，毛虫乃死，热后而暴，介虫乃殃，其发躁，胜复之作，扰而大乱，清热之气，持于气交。故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之、清之、散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化，用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。"}, "壬戌": {"STR": "运气异化", "NAME": "顺化年", "IF": "气生运,以气为主", "LEVELSTR": "岁运为太木(太角),司天为太阳寒水,在泉为太阴湿土,年支为戌土\r\n不是平气之年", "LEVELIS": "0", "SAME": "壬辰壬戌岁，上太阳水，中太角木运，下太阴土。寒化六，风化八，雨化五，正化度也。其化上苦温，中酸和，下甘温，药食宜也。", "COM": "壬辰壬戌，其运风，其化鸣紊启拆，其变振拉摧拔，其病眩掉目瞑。\r\n凡此太阳司天之政，气化运行先天，天气肃，地气静，寒凝太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯，止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物，寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡写血热。故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾，食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化，故同者多之，异者少之，用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。"}, "癸亥": {"STR": "运气同化", "NAME": "同岁会", "IF": "", "LEVELSTR": "岁运为少火(少徵),司天为厥阴风木,在泉为少阳相火,年支为亥水\r\n不是平气之年", "LEVELIS": "0", "SAME": "癸巳癸亥岁，上厥阴木，中少徵火运，下少阳相火，寒化雨化胜复同，邪气化度也。灾九宫。风化八，火化二，正化度也。其化上辛凉，中咸和，下咸寒，药食宜也。", "COM": "癸巳癸亥，其运热寒雨。凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天，天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹，间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。岁宜以辛调上，以咸调下，畏火之气，无妄犯之，用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也，反是者病。"}}, "YUNBACK": {"金太过": {"THREE": "金曰坚成\r\n坚成之纪，谓收引，天气洁，地气明，阳气随，阴治化，燥行其政，物以司成，收气繁布，化洽不终。其化成，其气削，其政肃，其令锐切，其动暴折疡疰，其德雾露萧飋，其变肃杀凋零，其谷稻黍，其畜鸡马，其果桃杏，其色白青丹，其味辛酸苦，其象秋，其经手太阴阳明，其藏肺肝，其虫介羽，其物壳络，其病喘喝，胸凭仰息。上徵与正商同，其生齐，其病咳，政暴变，则名木不营，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。", "OVER": "金胜.岁金太过，燥气流行，肝木受邪。民病两胁下少腹痛，目赤痛眥疡，耳无所闻。肃杀而甚，则体重烦冤，胸痛引背，两胁满且痛引少腹，上应太白星。甚则喘咳逆气，肩背痛，尻阴股膝髀（月耑）（骨行）足皆病，上应荧惑星。收气峻，生气下，草木敛，苍干凋陨，病反暴痛，胁不可反侧，咳逆甚而血溢，太冲绝者，死不治，上应太白星。", "BACK": "火复.上徵与正商同，其生齐，其病咳，政暴变，则名木不营，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。", "REBACK": "木郁.木郁之发，太虚埃昏，云物以扰，大风乃至，屋发折木，木有变。故民病胃脘当心而痛，上支两胁，鬲咽不通，食饮不下，甚则耳鸣眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或气浊色，黄黑郁若，横云不起，雨而乃发也，其气无常。长川草偃，柔叶呈阴，松吟高山，虎啸岩岫，怫之先兆也。"}, "金不及": {"THREE": "金曰从革\r\n从革之纪，是谓折收。收气乃后，生气乃扬，长化合德，火政乃宣，庶类以蕃。其气扬，其用躁切，其动铿禁瞀厥，其发咳喘，其藏肺，其果李杏，其实壳络，其谷麻麦，其味苦辛，其色白丹，其畜鸡羊，其虫介羽，其主明曜炎烁，其声商徵，其病嚏咳鼽衄，从火化也，少商与少徵同，上商与正商同，上角与正角同，邪伤肺也。炎光赫烈，则冰雪霜雹，眚于七，其主鳞伏彘鼠，岁气早至，乃生大寒。", "OVER": "火胜.岁金不及，炎火乃行，生气乃用，长气专胜，庶物以茂，燥烁以行，上应荧惑星，民病肩背瞀重，鼽嚏血便注下，收气乃后，上应太白星，其谷坚芒。", "BACK": "水复.复则寒雨暴至，乃零冰雹霜雪杀物，阴厥且格，阳反上行，头脑户痛，延及囟顶发热，上应辰星，丹谷不成，民病口疮，甚则心痛。\r\n少商与少徵同，上商与正商同，上角与正角同，邪伤肺也。炎光赫烈，则冰雪霜雹，眚于七，其主鳞伏彘鼠，岁气早至，乃生大寒。", "REBACK": "金郁.金郁之发，天洁地明，风清气切，大凉乃举，草树浮烟，燥气以行，霿雾数起，杀气来至，草木苍干，金乃有声。故民病咳逆，心胁满，引少腹善暴痛，不可反侧，嗌干面尘色恶。山泽焦枯，土凝霜卤，怫乃发也，其气五。夜零白露，林莽声凄，怫之兆也。"}, "木太过": {"THREE": "木曰发生\r\n发生之纪，是谓启陳，土疏泄，苍气达，阳和布化，阴气乃随，生气淳化，万物以荣。其化生，其气美，其政散，其令条舒，其动掉眩巅疾，其德鸣靡启坼，其变振拉摧拔，其谷麻稻，其畜鸡犬，其果李桃，其色青黄白，其味酸甘辛，其象春，其经足厥阴少阳，其藏肝脾，其虫毛介，其物中坚外坚，其病怒，太角与上商同，上徵则其气逆，其病吐利。不务其德，则收气复，秋气劲切，甚则肃杀，清气大至，草木凋零，邪乃伤肝。", "OVER": "木胜.岁木太过，风气流行，脾土受邪。民病飧泄，食减，体重，烦冤，肠鸣腹支满，上应岁星。甚则忽忽善怒，眩冒巅疾。化气不政，生气独治，云物飞动，草木不宁，甚而摇落，反胁痛而吐甚，冲阳绝者死不治，上应太白星。", "BACK": "金复.太角与上商同，上徵则其气逆，其病吐利。不务其德，则收气复，秋气劲切，甚则肃杀，清气大至，草木凋零，邪乃伤肝。", "REBACK": "土郁.土郁之发，岩谷震惊，雷殷气交，埃昏黄黑，化为白气，飘骤高深，击石飞空，洪水乃从，川流漫衍，田牧土驹。化气乃敷，善为时雨，始生始长，始化始成。故民病心腹胀，肠鸣而为数后，甚则心痛胁（月真），呕吐霍乱，饮发注下，胕肿身重。云奔雨府，霞拥朝阳，山泽埃昏。其乃发也，以其四气。云横天山，浮游生灭，怫之先兆。"}, "木不及": {"THREE": "木曰委和\r\n委和之纪，是谓胜生。生气不政，化气乃扬，长气自平，收令乃早。凉雨时降，风云并兴，草木晚荣，苍干凋落，物秀而实，肤肉内充。其气敛，其用聚，其动緛戾拘缓，其发惊骇，其藏肝，其果枣李，其实核壳，其谷稷稻，其味酸辛，其色白苍，其畜犬鸡，其虫毛介，其主雾露凄沧，其声角商。其病摇动注恐，从金化也，少角与判商同，上角与正角同，上商与正商同；其病支废肿疮疡，其甘虫，邪伤肝也，上宫与正宫同。萧飋肃杀，则炎赫沸腾，眚于三，所谓复也。其主飞蠹蛆雉，乃为雷霆。", "OVER": "金胜.岁木不及，燥乃大行，生气失应，草木晚荣，肃杀而甚，则刚木辟著，悉萎苍干，上应太白星，民病中清，胠胁痛，少腹痛，肠鸣溏泄，凉雨时至，上应太白星，其谷苍。上临阳明，生气失政，草木再荣，化气乃急，上应太白镇星，其主苍早。", "BACK": "火复.复则炎暑流火，湿性燥，柔脆草木焦槁，下体再生，华实齐化，病寒热疮疡疿胗痈痤，上应荧惑太白，其谷白坚。白露早降，收杀气行，寒雨害物，虫食甘黄，脾土受邪，赤气后化，心气晚治，上胜肺金，白气乃屈，其谷不成，咳而鼽，上应荧惑太白星。\r\n少角与判商同，上角与正角同，上商与正商同；其病支废肿疮疡，其甘虫，邪伤肝也，上宫与正宫同。萧飋肃杀，则炎赫沸腾，眚于三，所谓复也。其主飞蠹蛆雉，乃为雷霆。", "REBACK": "木郁.木郁之发，太虚埃昏，云物以扰，大风乃至，屋发折木，木有变。故民病胃脘当心而痛，上支两胁，鬲咽不通，食饮不下，甚则耳鸣眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或气浊色，黄黑郁若，横云不起，雨而乃发也，其气无常。长川草偃，柔叶呈阴，松吟高山，虎啸岩岫，怫之先兆也。"}, "水太过": {"THREE": "水曰流衍\r\n流衍之纪，是谓封藏，寒司物化，天地严凝，藏政以布，长令不扬。其化凛，其气坚，其政谧，其令流注，其动漂泄沃涌，其德凝惨寒雰，其变冰雪霜雹，其谷豆稷，其畜彘牛，其果栗枣，其色黑丹黅，其味咸苦甘，其象冬，其经足少阴太阳，其藏肾心，其虫鳞倮，其物濡满，其病胀，上羽而长气不化也。政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。故曰：不恒其德，则所胜来复，政恒其理，则所胜同化，此之谓也。", "OVER": "水胜.岁水太过，寒气流行，邪害心火。民病身热烦心，躁悸，阴厥上下中寒，谵妄心痛，寒气早至，上应辰星。甚则腹大胫肿，喘咳，寢汗出憎风，大雨至，埃雾朦郁，上应镇星。上临太阳，雨冰雪，霜不时降，湿气变物，病反腹满肠鸣溏泄，食不化，渴而妄冒，神门绝者，死不治，上应荧惑辰星。", "BACK": "土复.政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。", "REBACK": "火郁.火郁之发，太虚肿翳，大明不彰，炎火行，大暑至，山泽燔燎，材木流津，广厦腾烟，土浮霜卤，止水乃减，蔓草焦黄，风行惑言，湿化乃后。故民病少气，疮疡痈肿，胁腹胸背，面首四支（月真）愤，胪胀，疡痱，呕逆，瘛瘲骨痛，节乃有动，注下温疟，腹中暴痛，血溢流注，精液乃少，目赤心热，甚则瞀闷懊憹，善暴死。刻终大温，汗濡玄府，其乃发也，其气四。动复则静，阳极反阴，湿令乃化乃成。华发水凝，山川冰雪，焰阳午泽，怫之先兆也。有怫之应而后报也，皆观其极而乃发也，木发无时，水随火也。谨候其时，病可与期，失时反岁，五气不行，生化收藏，政无恒也。"}, "水不及": {"THREE": "水曰涸流\r\n涸流之纪，是谓反阳，藏令不举，化气乃昌，长气宣布，蛰虫不藏，土润水泉减，草木条茂，荣秀满盛。其气滞，其用渗泄，其动坚止，其发燥槁，其藏肾，其果枣杏，其实濡肉，其谷黍稷，其味甘咸，其色黅玄，甚畜彘牛，其虫鳞倮，其主埃郁昏翳，其声羽宫，其病痿厥坚下，从土化也，少羽与少宫同，上宫与正宫同，其病癃閟，邪伤肾也，埃昏骤雨，则振拉摧拔，眚于一，其主毛显狐（犭各），变化不藏。\r\n故乘危而行，不速而至，暴虐无德，灾反及之，微者复微，甚者复甚，气之常也。", "OVER": "土胜.岁水不及，湿乃大行，长气反用，其化乃速，暑雨数至，上应镇星，民病腹满身重，濡泄寒疡流水，腰股痛发，膕（月耑）股膝不便，烦冤，足痿，清厥，脚下痛，甚则跗肿，藏气不政，肾气不衡，上应辰星，其谷秬。上临太阴，则大寒数举，蛰虫早藏，地积坚冰，阳光不治，民病寒疾于下，甚则腹满浮肿，上应镇星，其主黅谷。", "BACK": "木复.复则大风暴发，草偃木零，生长不鲜，面色时变，筋骨并辟，肉（目閏）瘛，目视（目巟）（目巟），物疏璺，肌肉胗发，气并鬲中，痛于心腹，黄气乃损，其谷不登，上应岁星。\r\n少羽与少宫同，上宫与正宫同，其病癃閟，邪伤肾也，埃昏骤雨，则振拉摧拔，眚于一，其主毛显狐（犭各），变化不藏。", "REBACK": "水郁.水郁之发，阳气乃辟，阴气暴举，大寒乃至，川泽严凝，寒雰结为霜雪，甚则黄黑昏翳，流行气交，乃为霜杀，水乃见祥。故民病寒客心痛，腰（月隹）痛，大关节不利，屈伸不便，善厥逆，痞坚腹满。阳光不治，空积沉阴，白埃昏暝，而乃发也，其气二火前后。太虚深玄，气犹麻散，微见而隐，色黑微黄，怫之先兆也。"}, "火太过": {"THREE": "火曰赫曦\r\n赫曦之纪，是谓蕃茂，阴气内化，阳气外荣，炎暑施化，物得以昌。其化长，其气高，其政动，其令鸣显，其动炎灼妄扰，其德暄暑郁蒸，其变炎烈沸腾，其谷麦豆，其畜羊彘，其果杏栗，其色赤白玄，其味苦辛咸，其象夏，其经手少阴太阳，手厥阴少阳，其藏心肺，其虫羽鳞，其物脉濡，其病笑疟疮疡血流狂妄目赤，上羽与正徵同，其收齐，其病（疒至），上徵而收气后也。暴烈其政，藏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。", "OVER": "火胜.岁火太过，炎暑流行，金肺受邪。民病疟，少气咳喘，血溢血泄注下，嗌燥耳聋，中热肩背热，上应荧惑星。甚则胸中痛，胁支满胁痛，膺背肩胛间痛，两臂内痛，身热骨痛而为浸淫。收气不行，长气独明，雨水霜寒，上应辰星。上临少阴少阳，火燔（火芮），冰泉涸，物焦槁，病反谵妄狂越，咳喘息鸣，下甚血溢泄不已，太渊绝者死不治，上应荧惑星。", "BACK": "水复.上羽与正徵同，其收齐，其病（疒至），上徵而收气后也。暴烈其政，藏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。", "REBACK": "金郁.金郁之发，天洁地明，风清气切，大凉乃举，草树浮烟，燥气以行，霿雾数起，杀气来至，草木苍干，金乃有声。故民病咳逆，心胁满，引少腹善暴痛，不可反侧，嗌干面尘色恶。山泽焦枯，土凝霜卤，怫乃发也，其气五。夜零白露，林莽声凄，怫之兆也。"}, "火不及": {"THREE": "火曰伏明\r\n伏明之纪，是谓胜长。长气不宣，藏气反布，收气自政，化令乃衡，寒清数举，暑令乃薄。承化物生，生而不长，成实而稚，遇化已老，阳气屈伏，蛰虫早藏。其气郁，其用暴，其动彰伏变易，其发痛，其藏心，其果栗桃，其实络濡，其谷豆稻，其味苦咸，其色玄丹，其畜马彘，其虫羽鳞，其主冰雪霜寒，其声徵羽。其病昏惑悲忘，从水化也，少徵与少羽同，上商与正商同，邪伤心也。凝惨凓冽，则暴雨霖霪，眚于九，其主骤注雷霆震惊，沉（蕓去草頭令）淫雨。", "OVER": "水胜.岁火不及，寒乃大行，长政不用，物荣而下，凝惨而甚，则阳气不化，乃折荣美，上应辰星，民病胸中痛，胁支满，两胁痛，膺背肩胛间及两臂内痛，郁冒朦昧，心痛暴瘖，胸腹大，胁下与腰背相引而痛，甚则屈不能伸，髋髀如别，上应荧惑辰星，其谷丹。", "BACK": "土复.复则埃郁，大雨且至，黑气乃辱，病溏腹满，食饮不下，寒中肠鸣，泄注腹痛，暴挛痿痹，足不任身，上应镇星辰星，玄谷不成。\r\n少徵与少羽同，上商与正商同，邪伤心也。凝惨凓冽，则暴雨霖霪，眚于九，其主骤注雷霆震惊，沉（蕓去草頭令）淫雨。", "REBACK": "火郁.火郁之发，太虚肿翳，大明不彰，炎火行，大暑至，山泽燔燎，材木流津，广厦腾烟，土浮霜卤，止水乃减，蔓草焦黄，风行惑言，湿化乃后。故民病少气，疮疡痈肿，胁腹胸背，面首四支（月真）愤，胪胀，疡痱，呕逆，瘛瘲骨痛，节乃有动，注下温疟，腹中暴痛，血溢流注，精液乃少，目赤心热，甚则瞀闷懊憹，善暴死。刻终大温，汗濡玄府，其乃发也，其气四。动复则静，阳极反阴，湿令乃化乃成。华发水凝，山川冰雪，焰阳午泽，怫之先兆也。有怫之应而后报也，皆观其极而乃发也，木发无时，水随火也。谨候其时，病可与期，失时反岁，五气不行，生化收藏，政无恒也。"}, "土太过": {"THREE": "土曰敦阜\r\n敦阜之纪，是谓广化，厚德清静，顺长以盈，至阴内实，物化充成，烟埃朦郁，见于厚土，大雨时行，湿气乃用，燥政乃辟，其化员，其气丰，其政静，其令周备，其动濡积并稸，其德柔润重淖，其变震惊飘骤崩溃，其谷稷麻，其畜牛犬，其果枣李，其色黅玄苍，其味甘咸酸，其象长夏，其经足太阴阳明，其藏脾肾，其虫倮毛，其物肌核，其病腹满，四支不举，大风迅至，邪伤脾也。", "OVER": "土胜.岁土太过，雨湿流行，肾水受邪。民病腹痛，清厥意不乐，体重烦冤，上应镇星。甚则肌肉萎，足痿不收，行善瘈，脚下痛，饮发中满食减，四支不举。变生得位，藏气伏，化气独治之，泉涌河衍，涸泽生鱼，风雨大至，土崩溃，鳞见于陆，病腹满溏泄肠鸣，反下甚而太谿绝者，死不治，上应岁星。", "BACK": "木复.其藏脾肾，其虫倮毛，其物肌核，其病腹满，四支不举，大风迅至，邪伤脾也。", "REBACK": "水郁.水郁之发，阳气乃辟，阴气暴举，大寒乃至，川泽严凝，寒雰结为霜雪，甚则黄黑昏翳，流行气交，乃为霜杀，水乃见祥。故民病寒客心痛，腰（月隹）痛，大关节不利，屈伸不便，善厥逆，痞坚腹满。阳光不治，空积沉阴，白埃昏暝，而乃发也，其气二火前后。太虚深玄，气犹麻散，微见而隐，色黑微黄，怫之先兆也。"}, "土不及": {"THREE": "土曰卑监\r\n卑监之纪，是谓减化。化气不令，生政独彰，长气整，雨乃愆，收气平，风寒并兴，草木荣美，秀而不实，成而粃也。其气散，其用静定，其动疡涌分溃痈肿。其发濡滞，其藏脾，其果李栗，其实濡核，其谷豆麻，其味酸甘，其色苍黄，其畜牛犬，其虫倮毛，其主飘怒振发，其声宫角，其病留满否塞，从木化也，少宫与少角同，上宫与正宫同，上角与正角同，其病飧泄，邪伤脾也。振拉飘扬，则苍干散落，其眚四维，其主败折虎狼，清气乃用，生政乃辱。", "OVER": "木胜.岁土不及，风乃大行，化气不令，草木茂荣，飘扬而甚，秀而不实，上应岁星，民病飧泄霍乱，体重腹痛，筋骨繇复，肌肉（目闰）酸，善怒，藏气举事，蛰虫早附，咸病寒中，上应岁星镇星，其谷黅。", "BACK": "金复.复则收政严峻，名木苍凋，胸胁暴痛，下引少腹，善太息，虫食甘黄，气客于脾，黅谷乃减，民食少失味，苍谷乃损，上应太白岁星。上临厥阴，流水不冰，蛰虫来见，藏气不用，白乃不复，上应岁星，民乃康。\r\n少宫与少角同，上宫与正宫同，上角与正角同，其病飧泄，邪伤脾也。振拉飘扬，则苍干散落，其眚四维，其主败折虎狼，清气乃用，生政乃辱。", "REBACK": "土郁.土郁之发，岩谷震惊，雷殷气交，埃昏黄黑，化为白气，飘骤高深，击石飞空，洪水乃从，川流漫衍，田牧土驹。化气乃敷，善为时雨，始生始长，始化始成。故民病心腹胀，肠鸣而为数后，甚则心痛胁（月真），呕吐霍乱，饮发注下，胕肿身重。云奔雨府，霞拥朝阳，山泽埃昏。其乃发也，以其四气。云横天山，浮游生灭，怫之先兆。"}, "金平气": {"THREE": "金曰审平\r\n审平之纪，收而不争，杀而无犯，五化宣明，其气洁，其性刚，其用散落，其化坚敛，其类金，其政劲肃，其候清切，其令燥，其藏肺，肺其畏热，其主鼻，其谷稻，其果桃，其实壳，其应秋，其虫介，其畜鸡，其色白，其养皮毛，其病咳，其味辛，其音商，其物外坚，其数九。", "OVER": "", "BACK": "", "REBACK": ""}, "木平气": {"THREE": "木曰敷和\r\n敷和之纪，木德周行，阳舒阴布，五化宣平，其气端，其性随，其用曲直，其化生荣，其类草木，其政发散，其候温和，其令风，其藏肝，肝其畏清，其主目，其谷麻，其果李，其实核，其应春，其虫毛，其畜犬，其色苍，其养筋，其病里急支满，其味酸，其音角，其物中坚，其数八。", "OVER": "", "BACK": "", "REBACK": ""}, "水平气": {"THREE": "水曰静顺\r\n静顺之纪，藏而勿害，治而善下，五化咸整，其气明，其性下，其用沃衍，其化凝坚，其类水，其政流演，其候凝肃，其令寒，其藏肾，肾其畏湿，其主二阴，其谷豆，其果栗，其实濡，其应冬，其虫鳞，其畜彘，其色黑，其养骨髓，其病厥，其味咸，其音羽，其物濡，其数六。", "OVER": "", "BACK": "", "REBACK": ""}, "火平气": {"THREE": "火曰升明\r\n升明之纪，正阳而治，德施周普，五化均衡，其气高，其性速，其用燔灼，其化蕃茂，其类火，其政明曜，其候炎暑，其令热，其藏心，心其畏寒，其主舌，其谷麦，其果杏，其实络，其应夏，其虫羽，其畜马，其色赤，其养血，其病（目閏）瘛，其味苦，其音徵，其物脉，其数七。", "OVER": "", "BACK": "", "REBACK": ""}, "土平气": {"THREE": "土曰备化\r\n备化之纪，气协天休，德流四政，五化齐修，其气平，其性顺，其用高下，其化丰满，其类土，其政安静，其候溽蒸，其令湿，其藏脾，脾其畏风，其主口，其谷稷，其果枣，其实肉，其应长夏，其虫倮，其畜牛，其色黄，其养肉，其病否，其味甘，其音宫，其物肤，其数五。", "OVER": "", "BACK": "", "REBACK": ""}}, "QIBACK": {"阳明燥金": {"OVER": "阳明之胜，清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，大凉肃杀，华英改容，毛虫乃殃，胸中不便，嗌塞而咳。", "BACK": "火复.少阴之复，燠热内作，烦躁鼽嚏，少腹绞痛，火见燔（火芮），嗌燥，分注时止，气动于左，上行于右，咳，皮肤痛，暴瘖心痛，郁冒不知人，乃洒淅恶寒，振慄谵妄，寒已而热，渴而欲饮，少气骨痿，隔肠不便，外为浮肿，哕噫，赤气后化，流水不冰，热气大行，介虫不复，病疿胗疮疡，痈疽痤痔，甚则入肺，咳而鼻渊。天府绝，死不治。\r\n少阳之复，大热将至，枯燥燔（艹热），介虫乃耗，惊瘛咳衄，心热烦躁，便数憎风，厥气上行，面如浮埃，目乃（目閏）瘛，火气内发，上为口麋呕逆，血溢血泄，发而为疟，恶寒鼓慄，寒极反热，嗌络焦槁，渴引水浆，色变黄赤，少气脉萎，化而为水，传为胕肿，甚则入肺，咳而血泄。尺泽绝，死不治。", "OVER2": "阳明之胜，治以酸温，佐以辛甘，以苦泄之。", "BACK2": "少阴之复，治以咸寒，佐以苦辛，以甘写之，以酸收之，辛苦发之，以咸軟之。\r\n少阳之复，治以咸冷，佐以苦辛，以咸軟之，以酸收之，辛苦发之，发不远热，无犯温凉，少阴同法。"}, "厥阴风木": {"OVER": "厥阴之胜，耳鸣头眩，愦愦欲吐，胃鬲如寒，大风数举，倮虫不滋，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上支两胁，肠鸣飧泄，少腹痛，注下赤白，甚则呕吐，鬲咽不通。", "BACK": "金复.阳明之复，清气大举，森木苍干，毛虫乃厉，病生胠胁，气归于左，善太息，甚则心痛否满，腹胀而泄，呕苦咳哕，烦心，病在鬲中，头痛，甚则入肝，惊骇筋挛。太冲绝，死不治。", "OVER2": "厥阴之胜，治以甘清，佐以苦辛，以酸写之。", "BACK2": "阳明之复，治以辛温，佐以苦甘，以苦泄之，以苦下之，以酸补之。"}, "太阳寒水": {"OVER": "太阳之胜，凝凓且至，非时水冰，羽乃后化，痔疟发，寒厥入胃，则内生心痛，阴中乃疡，隐曲不利，互引阴股，筋肉拘苛，血脉凝泣，络满色变，或为血泄，皮肤否肿，腹满食减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，传为濡写。", "BACK": "土复.太阴之复，湿变乃举，体重中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声，大雨时行，鳞见于陆，头顶痛重，而掉瘛尤甚，呕而密默，唾吐清液，甚则入肾窍，写无度。太谿绝，死不治。", "OVER2": "太阳之胜，治以甘热，佐以辛酸，以咸写之。", "BACK2": "太阴之复，治以苦热，佐以酸辛，以苦写之，燥之，泄之。"}, "少阴君火": {"OVER": "少阴之胜，心下热，善饥，齐下反动，气游三焦，炎暑至，木乃津，草乃萎，呕逆躁烦，腹满痛，溏泄，传为赤沃。", "BACK": "水复.太阳之复，厥气上行，水凝雨冰，羽虫乃死。心胃生寒，胸膈不利，心痛否满，头痛善悲，时眩仆，食减，腰（月隹）反痛，屈伸不便，地裂冰坚，阳光不治，少腹控睾，引腰脊，上冲心，唾出清水，及为哕噫，甚则入心，善忘善悲。神门绝，死不治。", "OVER2": "少阴之胜，治以辛寒，佐以苦咸，以甘写之。", "BACK2": "太阳之复，治以咸热，佐以甘辛，以苦坚之。"}, "少阳相火": {"OVER": "少阳之胜，热客于胃，烦心心痛，目赤欲呕，呕酸善饥，耳痛溺赤，善惊谵妄，暴热消烁，草萎水涸，介虫乃屈，少腹痛，下沃赤白。", "BACK": "水复.太阳之复，厥气上行，水凝雨冰，羽虫乃死。心胃生寒，胸膈不利，心痛否满，头痛善悲，时眩仆，食减，腰（月隹）反痛，屈伸不便，地裂冰坚，阳光不治，少腹控睾，引腰脊，上冲心，唾出清水，及为哕噫，甚则入心，善忘善悲。神门绝，死不治。", "OVER2": "少阳之胜，治以辛寒，佐以甘咸，以甘写之。", "BACK2": "太阳之复，治以咸热，佐以甘辛，以苦坚之。"}, "太阴湿土": {"OVER": "太阴之胜，火气内郁，疮疡于中，流散于外，病在胠胁，甚则心痛，热格，头痛喉痹项强，独胜则湿气内郁，寒迫下焦，痛留顶，互引眉间，胃满，雨数至，燥化乃见，少腹满，腰（月隹）重强，内不便，善注泄，足下温，头重，足胫胕肿，饮发于中，胕肿于上。", "BACK": "木复.厥阴之复，少腹坚满，里急暴痛，偃木飞沙，倮虫不荣，厥心痛，汗发呕吐，饮食不入，入而复出，筋骨掉眩，清厥，甚则入脾，食痹而吐。冲阳绝，死不治。", "OVER2": "太阴之胜，治以咸热，佐以辛甘，以苦写之。", "BACK2": "厥阴之复，治以酸寒，佐以甘辛，以酸写之，以甘缓之。"}}, "SKYWATER": {"司天:阳明燥金": {"WIN": "阳明司天，燥淫所胜，则木乃晚荣，草乃晚生，筋骨内变，民病左胠胁痛，寒清于中，感而疟，大凉革候，咳，腹中鸣，注泄鶩溏，名木敛，生菀于下，草焦上首，心胁暴痛，不可反侧，嗌干面尘，腰痛，丈夫颓疝，妇人少腹痛，目昧眥，疡疮痤痈，蛰虫来见，病本于肝。太冲绝，死不治。", "FIX": "燥淫所胜，平以苦湿，佐以酸辛，以苦下之。"}, "司天:厥阴风木": {"WIN": "厥阴司天，风淫所胜，则太虚埃昏，云物以扰，寒生春气，流水不冰，民病胃脘当心而痛，上支两胁，鬲咽不通，饮食不下，舌本强，食则呕，冷泄腹胀，溏泄，瘕水闭，蛰虫不去，病本于脾。冲阳绝，死不治。", "FIX": "风淫所胜，平以辛凉，佐以苦甘，以甘缓之，以酸写之。"}, "司天:太阳寒水": {"WIN": "太阳司天，寒淫所胜，则寒气反至，水且冰，血变于中，发为痈疡，民病厥心痛，呕血血泄鼽衄，善悲，时眩仆，运火炎烈，雨暴乃雹，胸腹满，手热肘挛，掖肿，心澹澹大动，胸胁胃脘不安，面赤目黄，善噫嗌干，甚则色（火台），渴而欲饮，病本于心。神门绝，死不治。", "FIX": "寒淫所胜，平以辛热，佐以甘苦，以咸写之。"}, "司天:少阴君火": {"WIN": "少阴司天，热淫所胜，怫热至，火行其政，民病胸中烦热，嗌干，右胠满，皮肤痛，寒热咳喘，大雨且至，唾血血泄，鼽衄嚏呕，溺色变，甚则疮疡胕肿，肩背臂臑及缺盆中痛，心痛肺（月真），腹大满，膨膨而喘咳，病本于肺。尺泽绝，死不治。", "FIX": "热淫所胜，平以咸寒，佐以苦甘，以酸收之。"}, "司天:少阳相火": {"WIN": "少阳司天，火淫所胜，则温气流行，金政不平，民病头痛，发热恶寒而疟，热上皮肤痛，色变黄赤，传而为水，身面胕肿，腹满仰息，泄注赤白，疮疡咳唾血，烦心，胸中热，甚则鼽衄，病本于肺。天府绝，死不治。", "FIX": "火淫所胜，平以酸冷，佐以苦甘，以酸收之，以苦发之，以酸复之，热淫同。"}, "司天:太阴湿土": {"WIN": "太阴司天，湿淫所胜，则沉阴且布，雨变枯槁，胕肿骨痛，阴痹，阴痹者，按之不得，腰脊头项痛，时眩，大便难，阴气不用，饥不欲食，咳唾则有血，心如悬，病本于肾。太谿绝，死不治。", "FIX": "湿淫所胜，平以苦热，佐以酸辛，以苦燥之，以淡泄之。湿上甚而热，治以苦温，佐以甘辛，以汗为故而止。"}, "在泉:阳明燥金": {"WIN": "岁阳明在泉，燥淫所胜，则霿雾清瞑。民病喜呕，呕有苦，善太息，心胁痛不能反侧，甚则嗌干面尘，身无膏泽，足外反热。", "FIX": "燥淫于内，治以苦温，佐以甘辛，以苦下之。"}, "在泉:厥阴风木": {"WIN": "岁厥阴在泉，风淫所胜，则地气不明，平野昧，草乃早秀。民病洒洒振寒，善伸数欠，心痛支满，两胁里急，饮食不下，鬲咽不通，食则呕，腹胀善噫，得后与气，则快然如衰，身体皆重。", "FIX": "风淫于内，治以辛凉，佐以苦，以甘缓之，以辛散之。"}, "在泉:太阳寒水": {"WIN": "岁太阳在泉，寒淫所胜，则凝肃惨慄。民病少腹控睾，引腰脊，上冲心痛，血见，嗌痛颔肿。", "FIX": "寒淫于内，治以甘热，佐以苦辛，以咸写之，以辛润之，以苦坚之。"}, "在泉:少阴君火": {"WIN": "岁少阴在泉，热淫所胜，则焰浮川泽，阴处反明。民病腹中常鸣，气上冲胸，喘不能久立，寒热皮肤痛，目瞑齿痛（出页）肿，恶寒发热如疟，少腹中痛，腹大，蛰虫不藏。", "FIX": "热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。"}, "在泉:少阳相火": {"WIN": "岁少阳在泉，火淫所胜，则焰明郊野，寒热更至。民病注泄赤白，少腹痛溺赤，甚则血便，少阴同候。", "FIX": "火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。"}, "在泉:太阴湿土": {"WIN": "岁太阴在泉，草乃早荣，湿淫所胜，则埃昏岩谷，黄反见黑，至阴之交。民病饮积，心痛，耳聋，浑浑焞焞，嗌肿喉痹，阴病血见，少腹痛肿，不得小便，病冲头痛，目似脱，项似拔，腰似折，髀不可以回，膕如结，（月耑）如别。", "FIX": "湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。"}}};

/// JZ60：按年干支（如「甲子」）取到该年的字段字典（STR/NAME/IF/SAME/COM…）。
///
/// 注意：值为「字段字典」而非字符串，故返回 `Map<String, Map<String, String>>`；
/// 取某年大论原文用 `jz60Map[干支]!['SAME']`。
Map<String, Map<String, String>> get jz60Map =>
    _yunqiLiterature['JZ60'] as Map<String, Map<String, String>>;

/// YUNBACK：按「元素+太过/不及/平气」（如「金太过」「金平气」）取岁运三纪/胜/复/郁。
Map<String, Map<String, String>> get yunBackMap =>
    _yunqiLiterature['YUNBACK'] as Map<String, Map<String, String>>;

/// QIBACK：按六气名（如「阳明燥金」）取字段字典（OVER/BACK/OVER2/BACK2）。
Map<String, Map<String, String>> get qiBackMap =>
    _yunqiLiterature['QIBACK'] as Map<String, Map<String, String>>;

/// SKYWATER：按「司天:气名」/「在泉:气名」取字段字典（WIN/FIX）。
Map<String, Map<String, String>> get skyWaterMap =>
    _yunqiLiterature['SKYWATER'] as Map<String, Map<String, String>>;
